import java.util.*;

class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0;
        int best = 0;

        for (int right = 0; right < fruits.length; right++) {
            int fruit = fruits[right];
            count.put(fruit, count.getOrDefault(fruit, 0) + 1);

            while (count.size() > 2) {
                int outgoing = fruits[left];
                int next = count.get(outgoing) - 1;
                if (next == 0) {
                    count.remove(outgoing);
                } else {
                    count.put(outgoing, next);
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

class Solution {
    public int totalFruit(int[] fruits) {
        if (fruits.length == 0) {
            return 0;
        }

        int[] count = new int[fruits.length];
        int distinct = 0;
        int left = 0;
        int best = 0;

        for (int right = 0; right < fruits.length; right++) {
            int fruit = fruits[right];
            if (count[fruit] == 0) {
                distinct++;
            }
            count[fruit]++;

            while (distinct > 2) {
                int outgoing = fruits[left];
                count[outgoing]--;
                if (count[outgoing] == 0) {
                    distinct--;
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> lastSeen = new HashMap<>();
        int left = 0;
        int best = 0;

        for (int right = 0; right < fruits.length; right++) {
            lastSeen.put(fruits[right], right);

            if (lastSeen.size() > 2) {
                int earliestIndex = fruits.length;
                int typeToRemove = -1;
                for (Map.Entry<Integer, Integer> entry : lastSeen.entrySet()) {
                    if (entry.getValue() < earliestIndex) {
                        earliestIndex = entry.getValue();
                        typeToRemove = entry.getKey();
                    }
                }
                lastSeen.remove(typeToRemove);
                left = earliestIndex + 1;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

class Solution {
    public int totalFruit(int[] fruits) {
        int lastType = -1;
        int secondLastType = -1;
        int lastRunLength = 0;
        int currentWindow = 0;
        int best = 0;

        for (int fruit : fruits) {
            if (fruit == lastType || fruit == secondLastType) {
                currentWindow++;
            } else {
                currentWindow = lastRunLength + 1;
            }

            if (fruit == lastType) {
                lastRunLength++;
            } else {
                secondLastType = lastType;
                lastType = fruit;
                lastRunLength = 1;
            }

            best = Math.max(best, currentWindow);
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public int totalFruit(int[] fruits) {
        int best = 0;

        for (int start = 0; start < fruits.length; start++) {
            Set<Integer> types = new HashSet<>();
            for (int end = start; end < fruits.length; end++) {
                types.add(fruits[end]);
                if (types.size() > 2) {
                    break;
                }
                best = Math.max(best, end - start + 1);
            }
        }

        return best;
    }
}
